local formatTableModule = require(script.Parent.Parent.formatTable)
local formatTable = formatTableModule.formatTable

return function(plasma)
	local create = plasma.create
	return plasma.widget(function(debugger, cheatType)
		local custom = debugger._customWidgets
		local style = plasma.useStyle()
		local cheat, setCheat = plasma.useState("")

		local closed = plasma
			.window({
				title = cheatType,
				closable = true,
				maxSize = Vector2.new(300, style.panelHeight),
				minSize = Vector2.new(200, style.panelHeight),
			}, function()
				plasma.useInstance(function(ref)
					local playerProps = debugger.PlayerProps
					local funcs = debugger._funcs[cheatType] or {}
					
					local items = {}
					for i, v in pairs(funcs) do
						table.insert(items, {
							text = v.name,
							selected = false,
							object = v
						})
					end
					table.sort(items, function(a, b)
						return a.text < b.text
					end)
					for i, v in pairs(items) do
						v.selected = v.text == (debugger._cheating and debugger._cheating.name)
					end
					local selectedState = custom.selectionList(items):selected()
					if selectedState then
						if selectedState.text ~= cheat then
							debugger._cheatRes = nil
							setCheat(nil)
							debugger._cheating = nil
							spawn(function (args)
								wait()
								debugger._cheatRes = nil
								setCheat(selectedState.text)
								debugger._cheating = selectedState.object
							end)
						else
							debugger._cheatRes = nil
							setCheat(nil)
							debugger._cheating = nil
						end
					end
				end)
			end)
			:closed()

		if closed then
			return closed
		end
		return nil
	end)
end
